// 本人公开来源必要门；复用真实Interaction验证，不代完整死亡/受领World。
#include "resident/domains/family/bequest_disclosure_source.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;
// 失败保留原标签，避免只报汇总通过掩盖未到达的分支。
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
}
int main(){try{auto shared=std::make_shared<CommonCatalog>();CommonState seed;seed.identity.world_id[0]=8;seed.identity.execution_epoch=2;seed.identity.revision=5;seed.identity.tick=20;seed.metadata.scenario_id="scene";seed.metadata.player_actor_id="donor";seed.next_instance_id=99;shared->actor_ids={"donor","beneficiary"};shared->places.insert("home",{"home","town",{}});RoleDefinition role;role.id="contact";role.initial_actor="beneficiary";role.place_id="home";shared->roles.insert(role.id,role);seed.roles.insert(role.id,{"beneficiary",true,{}});for(const auto* name:{"donor","beneficiary"}){ActorRecord actor;actor.id=name;actor.alive=true;actor.available=true;actor.hp=100;actor.birth_tick=-20000;actor.location=SettlementLocation{"town","home"};seed.actors.insert(name,actor);}seed.facts.insert("family_bequest:2",{"family_bequest:2","family_bequest_declaration","family_bequest",{}});CommonStore c(seed,shared);FamilyBequestState grants;FamilyBequestDeclaration declaration;declaration.source.terms.donor_actor_id="donor";declaration.source.terms.beneficiary_actor_id="beneficiary";declaration.source.tick=1;declaration.source.revision=1;grants.declarations.insert("family_bequest:2",declaration);
InteractionCatalog catalog;catalog.common=shared;DialogueDefinition talk;talk.id="dialogue";talk.context_role="contact";talk.entry="talk";DialogueNode node;node.id="talk";node.kind="say";talk.nodes.push_back(node);catalog.dialogues.push_back(talk);InteractionState interactions;InteractionSession session;session.actor_id="donor";session.id="interaction:3";session.dialogue_id="dialogue";session.node_id="talk";session.phase="say";session.context={"home","beneficiary","contact"};interactions.interactions.push_back(session);InteractionAccess access;access.battle_occupied=[](const StableId&){return false;};access.resolve_location=[&](const StableId& actor){return c.actor(actor)->location;};access.role=[&](const StableId& id)->std::optional<RoleAssignmentView>{const auto* row=c.state().roles.find(id);return row?std::optional<RoleAssignmentView>{{row->actor_id,row->enabled}}:std::nullopt;};auto original=encode_common_state(c.state());auto quote=preview_bequest_disclosure(c,grants,interactions,catalog,access,"family_bequest:2");check(quote.ok,"real donor disclosure source missing");check(revalidate_bequest_disclosure(c,grants,interactions,catalog,access,quote.value).ok,"fresh meeting refused");auto absent=interactions;absent.interactions.clear();check(!preview_bequest_disclosure(c,grants,absent,catalog,access,"family_bequest:2").ok,"same place inferred delivery");auto pending=interactions;pending.interactions[0].phase="waiting";check(!preview_bequest_disclosure(c,grants,pending,catalog,access,"family_bequest:2").ok,"pending action disclosed");c.state().identity.execution_epoch++;check(!revalidate_bequest_disclosure(c,grants,interactions,catalog,access,quote.value).ok,"cold old callback survived");c.state().identity.execution_epoch--;check(compare_boundary(original,encode_common_state(c.state())).exact(),"pure source changed Common");
c.state().facts.insert("family_inheritance:4",{"family_inheritance:4","family_bequest_disclosed","family_inheritance",{}});FamilyBequestPlayerRead player=[](Integer,const StableId&)->Outcome<StableId>{return {true,"donor",{}};};FamilyDeathState life;auto historical=[&](const BequestDisclosureSource& source){return validate_bequest_disclosure_source(c,grants,life,catalog,player,source,"family_inheritance:4");};check(historical(quote.value.source).ok,"recorded meeting history refused");auto bad=quote.value.source;bad.beneficiary_actor_id="other";check(!historical(bad).ok,"disclosure widened recipient");bad=quote.value.source;bad.node_kind="action";check(!historical(bad).ok,"historical pending command accepted");grants.revocations.insert("family_bequest:5",{"family_bequest_revocation","family_bequest:2","donor",20,{}});c.state().facts.insert("family_bequest:5",{"family_bequest:5","family_bequest_revocation","family_bequest",{}});check(historical(quote.value.source).ok,"later revocation erased known content");check(!preview_bequest_disclosure(c,grants,interactions,catalog,access,"family_bequest:2").ok,"revoked declaration newly disclosed");
auto encoded=encode_bequest_disclosure_source(quote.value.source);auto decoded=decode_bequest_disclosure_source(encoded);check(decoded.ok&&bequest_disclosure_source_equal(decoded.value,quote.value.source),"JSON exact source lost");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_bequest_disclosure_source(writer,decoded.value).ok&&writer.finish().ok,"typed write failed");const auto& input=bytes;CodecVisitor reader(input);BequestDisclosureSource cold;check(visit_bequest_disclosure_source(reader,cold).ok&&reader.finish().ok&&compare_boundary(encoded,encode_bequest_disclosure_source(cold)).exact(),"typed source cold mismatch");auto corrupt=encoded;corrupt.find("context")->as<BoundaryValue::Dict>()->emplace_back("provider_actor_id",BoundaryValue{StableId("other")});check(!decode_bequest_disclosure_source(corrupt).ok,"nested provider duplicate accepted");corrupt=encoded;corrupt.as<BoundaryValue::Dict>()->emplace_back("declaration_id",BoundaryValue{StableId("other")});check(!decode_bequest_disclosure_source(corrupt).ok,"duplicate declaration accepted");std::cout<<"BEQUEST_DISCLOSURE_SOURCE "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<"BEQUEST_DISCLOSURE_SOURCE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
